         {
             return word;
         }

         if (_uncountables.Contains(word))
         {
             return word;
         }

         if (_irregularSingulars.TryGetValue(word, out var irregularSingular))
         {
             return irregularSingular;
         }

         return ApplyRules(_singulars, word) ?? word;
     }

